                Progress = JsonConvert.DeserializeObject<PlayerProgress>(json);

                if (Progress.worldId != _worldId)
                {
                    Progress.playerPosition = new Vector3Serializable(Vector3.zero);
                }
            }
            else
            {
                Progress = new PlayerProgress();
            }
